CREATE FUNCTION qf.consumer_json_valid_v2(v jsonb,s jsonb,d integer) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE x jsonb; k text; typ text; str text; units integer; matches integer:=0;
BEGIN
 IF d>32 OR s IS NULL THEN RETURN false; END IF;
 IF jsonb_typeof(s->'type')='array' THEN
  FOR x IN SELECT value FROM jsonb_array_elements(s->'type') LOOP IF qf.consumer_json_valid_v2(v,jsonb_set(s,'{type}',x),d+1) THEN RETURN true; END IF; END LOOP;
  RETURN false;
 END IF;
 IF s ? 'allOf' THEN FOR x IN SELECT value FROM jsonb_array_elements(s->'allOf') LOOP IF qf.consumer_json_valid_v2(v,x,d) IS NOT TRUE THEN RETURN false; END IF; END LOOP; END IF;
 IF s ? 'anyOf' OR s ? 'oneOf' THEN
  FOR x IN SELECT value FROM jsonb_array_elements(coalesce(s->'anyOf',s->'oneOf')) LOOP IF qf.consumer_json_valid_v2(v,x,d) THEN matches:=matches+1; END IF; END LOOP;
  IF matches=0 OR (s ? 'oneOf' AND matches<>1) THEN RETURN false; END IF;
 END IF;
 IF s ? 'const' AND v IS DISTINCT FROM s->'const' THEN RETURN false; END IF;
 IF s ? 'enum' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'enum') e WHERE e=v) THEN RETURN false; END IF;
 typ:=s->>'type';
 IF typ IS NOT NULL AND NOT (jsonb_typeof(v)=typ OR (typ='integer' AND jsonb_typeof(v)='number' AND (v::text)::numeric=trunc((v::text)::numeric))) THEN RETURN false; END IF;
 CASE jsonb_typeof(v)
 WHEN 'object' THEN
  IF s->'additionalProperties'='false'::jsonb AND EXISTS(SELECT 1 FROM jsonb_object_keys(v) a WHERE NOT coalesce(s->'properties','{}'::jsonb) ? a) THEN RETURN false; END IF;
  IF s ? 'required' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(s->'required') a WHERE NOT v ? a) THEN RETURN false; END IF;
  FOR k,x IN SELECT key,value FROM jsonb_each(v) LOOP IF s->'properties' ? k AND qf.consumer_json_valid_v2(x,s->'properties'->k,d+1) IS NOT TRUE THEN RETURN false; END IF; END LOOP;
 WHEN 'array' THEN
  IF jsonb_array_length(v)<coalesce((s->>'minItems')::integer,0) OR jsonb_array_length(v)>coalesce((s->>'maxItems')::integer,10000) THEN RETURN false; END IF;
  IF s ? 'items' THEN FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP IF qf.consumer_json_valid_v2(x,s->'items',d+1) IS NOT TRUE THEN RETURN false; END IF; END LOOP; END IF;
 WHEN 'string' THEN
  str:=v#>>'{}'; SELECT length(str)+count(*) FILTER(WHERE ascii(c)>65535)::integer INTO units FROM regexp_split_to_table(str,'') c;
  IF units<coalesce((s->>'minLength')::integer,0) OR units>coalesce((s->>'maxLength')::integer,524288) THEN RETURN false; END IF;
  -- PostgreSQL ARE bounds repetitions at 255. This fixed JS all-code-unit bound is checked as UTF-16 length.
  IF s->>'pattern'=$regex$^[\s\S]{1,400}(?![\s\S])$regex$ THEN
   IF units<1 OR units>400 THEN RETURN false; END IF;
  ELSIF s ? 'pattern' AND str !~ replace(s->>'pattern',$regex$[\s\S]$regex$,'.') THEN RETURN false; END IF;
 WHEN 'number' THEN IF (s ? 'minimum' AND (v::text)::numeric<(s->>'minimum')::numeric) OR (s ? 'maximum' AND (v::text)::numeric>(s->>'maximum')::numeric) THEN RETURN false; END IF;
 ELSE NULL;
 END CASE;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE FUNCTION qf.consumer_body_valid_v2(t text,kind text,maximum integer) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE v jsonb;
BEGIN
 IF octet_length(t)<2 OR octet_length(t)>maximum THEN RETURN false; END IF;
 v:=t::jsonb;
 RETURN (qf.consumer_json_valid_v2(v,qf.consumer_schema_v2(kind),0) AND t=qf.consumer_canonical(v)) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;


CREATE OR REPLACE FUNCTION qf.internal_version_valid(r qf.product_version) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE b jsonb; s jsonb; t jsonb;
BEGIN
 b:=r.binding_text::jsonb; s:=r.snapshot_text::jsonb;
 t:=jsonb_build_object('draftId',r.draft_id,'revision',r.revision,'canonicalContentSha256',r.canonical_content_sha256::text,'assetSetSha256',r.asset_set_sha256::text,'canonicalManifestSha256',r.canonical_manifest_sha256::text);
 IF s->>'contentSchemaVersion'='quizpack-content.v3' AND (qf.consumer_body_valid_v2(r.snapshot_text,'version',32768) AND s#>>'{versions,engine,id}'='archetype-l1' AND s#>>'{versions,engine,version}'='1.0.0') IS NOT TRUE THEN RETURN false; END IF;
 RETURN (r.binding_text=qf.internal_canonical(b) AND r.fingerprint::text=qf.sha256_utf8(r.binding_text)
 AND b=jsonb_build_object('schemaVersion','quizforge.internal-version-seal.v1','productId',r.product_id,'idempotencyKey',r.idempotency_key,'target',t,'reviewId',r.review_id,'reviewSha256',r.review_sha256::text,'renderer',b->'renderer','engine',b->'engine')
 AND qf.internal_registry_identity(b->'renderer','renderer') AND qf.internal_registry_identity(b->'engine','engine')
 AND r.snapshot_text=qf.internal_canonical(s) AND r.snapshot_sha256::text=qf.sha256_utf8(r.snapshot_text)
 AND s=jsonb_build_object('schemaVersion',CASE WHEN s->>'contentSchemaVersion'='quizpack-content.v3' THEN 'quizforge.internal-version-snapshot.v2' ELSE 'quizforge.internal-version-snapshot.v1' END,'productId',r.product_id,'target',t,'reviewId',r.review_id,'reviewSha256',r.review_sha256::text,'baseline',s->'baseline','purpose',r.purpose,'publicationApproved',r.publication_approved,'contentSchemaVersion',s->'contentSchemaVersion','contentKind',s->'contentKind','packId',s->'packId','packVersion',s->'packVersion','versions',s->'versions','logicHash',s->'logicHash','renderer',b->'renderer','rendererCapability','studio-internal-preview','components',s->'components','engine',b->'engine','font',s->'font','validation',s->'validation')
 AND qf.internal_registry_identity(s->'baseline','baseline') AND s->>'logicHash' ~ '^[a-f0-9]{64}$'
 AND s->>'contentSchemaVersion' IN ('quizpack-content.v2','quizpack-content.v3') AND s->>'contentKind' IN ('synthetic','authored')
 AND s->'versions'->>'componentVersion'=CASE WHEN s->>'contentSchemaVersion'='quizpack-content.v3' THEN '1.0.0' ELSE '2.0.0' END AND s->'versions'->'engine'->>'id'=b->'engine'->>'id' AND s->'versions'->'engine'->>'version'=b->'engine'->>'version') IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.consumer_play_valid(r qf.internal_play_version) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE b jsonb; s jsonb;
BEGIN
 b:=r.binding_text::jsonb;s:=r.snapshot_text::jsonb;
 IF qf.consumer_body_valid(r.binding_text,'play_binding',8192) IS NOT TRUE OR (CASE WHEN s->>'schemaVersion'='quizforge.internal-play-snapshot.v2' THEN qf.consumer_body_valid_v2(r.snapshot_text,'play',65536) ELSE qf.consumer_body_valid(r.snapshot_text,'play',65536) END) IS NOT TRUE THEN RETURN false; END IF;
 IF s->>'schemaVersion'='quizforge.internal-play-snapshot.v2' AND ((s#>>'{presentation,presentationMode}'='structured-only' AND s#>'{presentation,exports}'=jsonb_build_object('posterPng',false,'fullReportPng',false) AND s#>>'{parentSnapshot,font,kind}'='system-structured') OR (s#>>'{presentation,presentationMode}'='authored-product' AND NOT(s#>'{parentSnapshot,font}' ? 'kind'))) IS NOT TRUE THEN RETURN false; END IF;
 RETURN (r.binding_sha256::text=qf.sha256_utf8(r.binding_text) AND r.snapshot_sha256::text=qf.sha256_utf8(r.snapshot_text) AND qf.consumer_moment(r.created_at) IS NOT NULL
 AND b->>'operationKey'=r.operation_key::text AND b->'parent'=jsonb_build_object('productId',r.product_id,'versionId',r.parent_version_id,'snapshotSha256',r.parent_snapshot_sha256::text)
 AND b->'parent'=s->'parent' AND b->'renderer'=s->'renderer' AND s->>'mappingSha256'=qf.sha256_utf8(qf.consumer_canonical(s->'mapping'))
 AND s->'parentSnapshot'->>'productId'=r.product_id AND s->'resources'->>'productId'=r.product_id
 AND NOT EXISTS(SELECT 1 FROM jsonb_each(s->'mapping'->'states') a WHERE a.value->'source' IS DISTINCT FROM s->'parentSnapshot'->'components'->a.key)) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

-- Fixed play, parent and protocol tuple is the only dispatch authority. Missing/mixed tuples return NULL.
CREATE FUNCTION qf.consumer_protocol_v2(product_id text,play_id uuid,play_sha text) RETURNS boolean LANGUAGE plpgsql STABLE STRICT SET search_path=pg_catalog AS $$
DECLARE r qf.internal_play_version; s jsonb;
BEGIN
 SELECT * INTO r FROM qf.internal_play_version p WHERE p.id=play_id AND p.product_id=consumer_protocol_v2.product_id AND p.snapshot_sha256=play_sha;
 IF NOT FOUND OR qf.consumer_play_valid(r) IS NOT TRUE THEN RETURN NULL; END IF;
 s:=r.snapshot_text::jsonb;
 IF s->>'schemaVersion'='quizforge.internal-play-snapshot.v1' AND s#>>'{parentSnapshot,schemaVersion}'='quizforge.internal-version-snapshot.v1' AND s#>>'{parentSnapshot,contentSchemaVersion}'='quizpack-content.v2' THEN RETURN false; END IF;
 IF s->>'schemaVersion'='quizforge.internal-play-snapshot.v2' AND s#>>'{parentSnapshot,schemaVersion}'='quizforge.internal-version-snapshot.v2' AND s#>>'{parentSnapshot,contentSchemaVersion}'='quizpack-content.v3' AND s#>>'{parentSnapshot,versions,engine,id}'='archetype-l1' AND s#>>'{parentSnapshot,versions,engine,version}'='1.0.0' THEN RETURN true; END IF;
 RETURN NULL;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END $$;

ALTER TABLE qf.consumer_session ADD COLUMN matching_context_text text, ADD COLUMN matching_context_sha256 char(64);
ALTER TABLE qf.quiz_report ADD COLUMN matching_context_sha256 char(64);
ALTER TABLE qf.consumer_session ADD CONSTRAINT consumer_session_final_context UNIQUE(id,key_id,product_id,play_version_id,play_snapshot_sha256,state_revision,consumer_state_answers_sha256,progress_sha256,matching_context_sha256);
-- Keep quiz_report_session_final unchanged. Legacy v1 has SQL NULL only in the added context column.
ALTER TABLE qf.quiz_report ADD CONSTRAINT quiz_report_session_final_context FOREIGN KEY(session_id,key_id,product_id,play_version_id,play_snapshot_sha256,state_revision,consumer_state_answers_sha256,progress_sha256,matching_context_sha256)
 REFERENCES qf.consumer_session(id,key_id,product_id,play_version_id,play_snapshot_sha256,state_revision,consumer_state_answers_sha256,progress_sha256,matching_context_sha256) MATCH SIMPLE ON UPDATE RESTRICT ON DELETE RESTRICT;


CREATE FUNCTION qf.consumer_session_valid_v1(r qf.consumer_session) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE a jsonb; p jsonb; b jsonb; receipt jsonb; ref jsonb;
BEGIN
 IF qf.consumer_body_valid(r.answers_text,'answers',65536) IS NOT TRUE OR qf.consumer_body_valid(r.progress_text,'progress',4096) IS NOT TRUE THEN RETURN false; END IF;
 a:=r.answers_text::jsonb;p:=r.progress_text::jsonb;
 IF (r.consumer_state_answers_sha256::text=qf.sha256_utf8(r.answers_text) AND r.progress_sha256::text=qf.sha256_utf8(r.progress_text) AND qf.consumer_moment(r.created_at) IS NOT NULL) IS NOT TRUE THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM (SELECT value->>'questionId' q,lag(value->>'questionId') OVER(ORDER BY ordinal) prev FROM jsonb_array_elements(a->'answers') WITH ORDINALITY t(value,ordinal)) t WHERE prev COLLATE "C">=q COLLATE "C") THEN RETURN false; END IF;
 IF r.state_revision=0 THEN RETURN (a->'answers'='[]'::jsonb AND p->'progress'=jsonb_build_object('questionId',NULL) AND r.last_binding_text IS NULL AND r.last_binding_sha256 IS NULL AND r.last_receipt_text IS NULL AND r.last_receipt_sha256 IS NULL) IS TRUE; END IF;
 IF r.last_binding_text IS NULL OR r.last_binding_sha256 IS NULL OR r.last_receipt_text IS NULL OR r.last_receipt_sha256 IS NULL OR qf.consumer_body_valid(r.last_binding_text,'save',4096) IS NOT TRUE OR qf.consumer_body_valid(r.last_receipt_text,'save_receipt',8192) IS NOT TRUE THEN RETURN false; END IF;
 b:=r.last_binding_text::jsonb;receipt:=r.last_receipt_text::jsonb;
 ref:=jsonb_build_object('productId',r.product_id,'playVersionId',r.play_version_id,'playSnapshotSha256',r.play_snapshot_sha256::text,'keyId',r.key_id,'sessionId',r.id);
 RETURN (r.last_binding_sha256::text=qf.sha256_utf8(r.last_binding_text) AND r.last_receipt_sha256::text=qf.sha256_utf8(r.last_receipt_text)
 AND b=jsonb_build_object('schemaVersion','quizforge.consumer-save.v1','session',ref,'expectedStateRevision',r.state_revision-1,'consumerStateAnswersSha256',r.consumer_state_answers_sha256::text,'progressSha256',r.progress_sha256::text)
 AND receipt->'binding'=b AND receipt->>'bindingSha256'=r.last_binding_sha256::text AND receipt->'appliedStateRevision'=to_jsonb(r.state_revision)) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.consumer_session_valid(r qf.consumer_session) RETURNS boolean LANGUAGE plpgsql STABLE STRICT SET search_path=pg_catalog AS $$
DECLARE a jsonb; p jsonb; b jsonb; receipt jsonb; ref jsonb; is_v2 boolean; context jsonb;
BEGIN
 is_v2:=qf.consumer_protocol_v2(r.product_id,r.play_version_id,r.play_snapshot_sha256::text);
 IF is_v2 IS NULL THEN RETURN false; END IF;
 IF NOT is_v2 THEN RETURN (r.matching_context_text IS NULL AND r.matching_context_sha256 IS NULL AND qf.consumer_session_valid_v1(r)) IS TRUE; END IF;
 IF (r.matching_context_text IS NOT NULL AND r.matching_context_sha256 IS NOT NULL AND qf.consumer_body_valid_v2(r.matching_context_text,'context',4096) AND r.matching_context_sha256::text=qf.sha256_utf8(E'quizforge:quiz-matching-context.v1\n'||r.matching_context_text)) IS NOT TRUE THEN RETURN false; END IF;
 context:=r.matching_context_text::jsonb;
 IF qf.consumer_body_valid(r.answers_text,'answers',65536) IS NOT TRUE OR qf.consumer_body_valid(r.progress_text,'progress',4096) IS NOT TRUE THEN RETURN false; END IF;
 a:=r.answers_text::jsonb;p:=r.progress_text::jsonb;
 IF (r.consumer_state_answers_sha256::text=qf.sha256_utf8(r.answers_text) AND r.progress_sha256::text=qf.sha256_utf8(r.progress_text) AND qf.consumer_moment(r.created_at) IS NOT NULL) IS NOT TRUE THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM (SELECT value->>'questionId' q,lag(value->>'questionId') OVER(ORDER BY ordinal) prev FROM jsonb_array_elements(a->'answers') WITH ORDINALITY t(value,ordinal)) t WHERE prev COLLATE "C">=q COLLATE "C") THEN RETURN false; END IF;
 IF r.state_revision=0 THEN RETURN (r.matching_context_text='null' AND a->'answers'='[]'::jsonb AND p->'progress'=jsonb_build_object('questionId',NULL) AND r.last_binding_text IS NULL AND r.last_binding_sha256 IS NULL AND r.last_receipt_text IS NULL AND r.last_receipt_sha256 IS NULL) IS TRUE; END IF;
 IF context='null'::jsonb THEN RETURN false; END IF;
 IF r.last_binding_text IS NULL OR r.last_binding_sha256 IS NULL OR r.last_receipt_text IS NULL OR r.last_receipt_sha256 IS NULL OR qf.consumer_body_valid_v2(r.last_binding_text,'save',4096) IS NOT TRUE OR qf.consumer_body_valid_v2(r.last_receipt_text,'save_receipt',8192) IS NOT TRUE THEN RETURN false; END IF;
 b:=r.last_binding_text::jsonb;receipt:=r.last_receipt_text::jsonb;
 ref:=jsonb_build_object('productId',r.product_id,'playVersionId',r.play_version_id,'playSnapshotSha256',r.play_snapshot_sha256::text,'keyId',r.key_id,'sessionId',r.id);
 RETURN (r.last_binding_sha256::text=qf.sha256_utf8(r.last_binding_text) AND r.last_receipt_sha256::text=qf.sha256_utf8(r.last_receipt_text)
 AND b=jsonb_build_object('schemaVersion','quizforge.consumer-save.v2','session',ref,'expectedStateRevision',r.state_revision-1,'consumerStateAnswersSha256',r.consumer_state_answers_sha256::text,'progressSha256',r.progress_sha256::text,'matchingContextSha256',r.matching_context_sha256::text)
 AND receipt->>'schemaVersion'='quizforge.consumer-save-receipt.v2' AND receipt->'binding'=b AND receipt->>'bindingSha256'=r.last_binding_sha256::text AND receipt->'appliedStateRevision'=to_jsonb(r.state_revision)) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.protect_consumer_session() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE k qf.access_key; source jsonb; progress jsonb; is_v2 boolean; questions jsonb; context jsonb;
BEGIN
 IF NOT pg_try_advisory_xact_lock_shared(72461,2) THEN RAISE EXCEPTION 'CONSUMER_MAINTENANCE_BUSY' USING ERRCODE='55P03'; END IF;
 SELECT * INTO k FROM qf.access_key WHERE id=NEW.key_id FOR UPDATE;
 IF NOT FOUND OR k.revoked_at IS NOT NULL OR k.void_operation_key IS NOT NULL OR k.void_binding_text IS NOT NULL OR k.void_binding_sha256 IS NOT NULL OR k.voided_by IS NOT NULL THEN RAISE EXCEPTION 'CONSUMER_KEY_VOID' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state_revision<>0 OR k.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'CONSUMER_INVALID_CLAIM' USING ERRCODE='23514'; END IF;
 ELSE
  IF ROW(NEW.id,NEW.key_id,NEW.product_id,NEW.play_version_id,NEW.play_snapshot_sha256,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.key_id,OLD.product_id,OLD.play_version_id,OLD.play_snapshot_sha256,OLD.created_at) OR NEW.state_revision::bigint<>OLD.state_revision::bigint+1 THEN RAISE EXCEPTION 'CONSUMER_INVALID_REVISION' USING ERRCODE='23514'; END IF;
 END IF;
 SELECT d.canonical_content_text::jsonb INTO source FROM qf.internal_play_version p JOIN qf.product_version v ON(v.id,v.product_id,v.snapshot_sha256)=(p.parent_version_id,p.product_id,p.parent_snapshot_sha256) JOIN qf.draft_revision d ON(d.product_id,d.draft_id,d.revision)=(v.product_id,v.draft_id,v.revision) WHERE p.id=NEW.play_version_id AND p.product_id=NEW.product_id AND p.snapshot_sha256=NEW.play_snapshot_sha256;
 IF NOT FOUND THEN RAISE EXCEPTION 'CONSUMER_SOURCE_MISSING' USING ERRCODE='23514'; END IF;
 is_v2:=qf.consumer_protocol_v2(NEW.product_id,NEW.play_version_id,NEW.play_snapshot_sha256::text);
 IF is_v2 IS NULL THEN RAISE EXCEPTION 'CONSUMER_PROTOCOL_MISMATCH' USING ERRCODE='23514'; END IF;
 IF is_v2 THEN
  IF source->>'schemaVersion'<>'quizpack-content.v3' OR NEW.matching_context_text IS NULL OR NEW.matching_context_sha256 IS NULL THEN RAISE EXCEPTION 'CONSUMER_CONTEXT_REQUIRED' USING ERRCODE='23514'; END IF;
  context:=NEW.matching_context_text::jsonb;
  IF context<>'null'::jsonb AND context->'policyRef' IS DISTINCT FROM source#>'{core,scoringDefinition,matchingPolicy,ref}' THEN RAISE EXCEPTION 'CONSUMER_CONTEXT_POLICY' USING ERRCODE='23514'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',q#>>'{ref,id}','options',(SELECT jsonb_agg(jsonb_build_object('id',o#>>'{ref,id}')) FROM jsonb_array_elements(q->'options') o))),'[]'::jsonb) INTO questions FROM jsonb_array_elements(source#>'{core,questions}') q;
 ELSE
  IF source->>'schemaVersion'<>'quizpack-content.v2' OR NEW.matching_context_text IS NOT NULL OR NEW.matching_context_sha256 IS NOT NULL THEN RAISE EXCEPTION 'CONSUMER_PROTOCOL_MISMATCH' USING ERRCODE='23514'; END IF;
  questions:=source->'questions';
 END IF;
 IF jsonb_typeof(questions)<>'array' OR jsonb_array_length(questions)=0 THEN RAISE EXCEPTION 'CONSUMER_SOURCE_MISSING' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.answers_text::jsonb->'answers') a WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(questions) q CROSS JOIN LATERAL jsonb_array_elements(q->'options') o WHERE q->>'id'=a->>'questionId' AND o->>'id'=a->>'optionId')) THEN RAISE EXCEPTION 'CONSUMER_INVALID_ANSWER' USING ERRCODE='23514'; END IF;
 progress:=NEW.progress_text::jsonb->'progress'->'questionId';
 IF progress IS DISTINCT FROM 'null'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(questions) q WHERE q->'id'=progress) THEN RAISE EXCEPTION 'CONSUMER_INVALID_PROGRESS' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;

-- These immutable helpers validate the six-volume source facts; they never call a renderer or a model.
CREATE FUNCTION qf.composed_quote_v1(source jsonb,e jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('questionRef',q->'ref','optionRef',o->'ref','prompt',q->'prompt','optionText',o->'label','scope',e->'scope')
 FROM jsonb_array_elements(source#>'{core,questions}') q CROSS JOIN LATERAL jsonb_array_elements(q->'options') o WHERE q->'ref'=e->'questionRef' AND o->'ref'=e->'optionRef'
$$;
CREATE FUNCTION qf.composed_role_v1(source jsonb,ranked jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('ref',r->'ref','label',r->'label','kind',p->'kind','narrativeIndex',ranked->'narrativeIndex') FROM jsonb_array_elements(source#>'{core,results}') r CROSS JOIN jsonb_array_elements(source#>'{core,scoringDefinition,profiles}') p WHERE r->'ref'=ranked->'resultRef' AND p->'resultRef'=r->'ref'
$$;
CREATE FUNCTION qf.composed_body_v1(source jsonb,scored jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE core jsonb; bindings jsonb; score jsonb; template jsonb; volume jsonb; claim_ref jsonb; claim jsonb; e jsonb; family jsonb; fixed_q jsonb; fixed_o jsonb; dim jsonb; effect integer; wanted integer; supporters text[]; opposite boolean; allowed boolean; matched boolean; paragraphs jsonb; volumes jsonb:='[]'; evidence jsonb; counterevidence jsonb; answers jsonb; dimensions jsonb;
BEGIN
 core:=source->'core'; bindings:=source->'bindings'; score:=scored->'score';
 SELECT t INTO template FROM jsonb_array_elements(bindings->'reportTemplates') t WHERE t->'ref'=scored->'reportTemplateRef';
 IF template IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(bindings->'resultReports') m WHERE m->'resultRef'=score#>'{decision,selectedResultRef}' AND m->'templateRef'=template->'ref') THEN RETURN NULL; END IF;
 FOR volume IN SELECT value FROM jsonb_array_elements(template->'volumes') LOOP
  paragraphs:='[]';
  FOR claim_ref IN SELECT value FROM jsonb_array_elements(volume->'claimRefs') LOOP
   SELECT c INTO claim FROM jsonb_array_elements(template->'claims') c WHERE c->'ref'=claim_ref;
   IF claim IS NULL THEN RETURN NULL; END IF;
   matched:=true;
   FOR e IN SELECT value FROM jsonb_array_elements((claim->'evidence')||(claim->'counterevidence')||(claim#>'{when,answers}')) LOOP
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(score->'normalizedAnswers') a WHERE a->>'questionId'=e#>>'{questionRef,id}' AND a->>'optionId'=e#>>'{optionRef,id}') THEN matched:=false; EXIT; END IF;
   END LOOP;
   SELECT d INTO dim FROM jsonb_array_elements(score->'dimensions') d WHERE d->'dimensionRef'=claim->'dimensionRef';
   IF dim IS NULL THEN RETURN NULL; END IF;
   IF claim#>'{when,selectedResultRef}'<>'null'::jsonb AND claim#>'{when,selectedResultRef}' IS DISTINCT FROM score#>'{decision,selectedResultRef}' THEN matched:=false; END IF;
   IF claim#>'{when,scoreRange}'<>'null'::jsonb AND ((dim->>'score')::integer<(claim#>>'{when,scoreRange,min}')::integer OR (dim->>'score')::integer>(claim#>>'{when,scoreRange,max}')::integer) THEN matched:=false; END IF;
   IF claim#>'{when,nearTie}'<>'null'::jsonb AND claim#>'{when,nearTie}' IS DISTINCT FROM to_jsonb(score#>>'{decision,status}'='near-tie') THEN matched:=false; END IF;
   IF NOT matched THEN CONTINUE; END IF;
   allowed:=true;
   IF claim->>'kind'='summary' THEN
    wanted:=CASE claim->>'direction' WHEN 'high' THEN 1 ELSE -1 END; supporters:='{}';opposite:=false;
    FOR family IN SELECT f FROM jsonb_array_elements(core#>'{evidenceFamilies,entries}') f WHERE f->'core'='true'::jsonb AND f->'dimensionRef'=claim->'dimensionRef' LOOP
     SELECT question INTO fixed_q FROM jsonb_array_elements(core#>'{scoringDefinition,questions}') question WHERE question->'ref'=family->'questionRef';
     SELECT option INTO fixed_o FROM jsonb_array_elements(fixed_q->'options') option WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(score->'normalizedAnswers') a WHERE a->>'questionId'=fixed_q#>>'{ref,id}' AND a->>'optionId'=option#>>'{ref,id}');
     SELECT (c->>'value')::integer INTO effect FROM jsonb_array_elements(fixed_o->'contributions') c WHERE c->'dimensionRef'=family->'dimensionRef';
     IF effect IS NULL THEN RETURN NULL; END IF;
     IF sign(effect)=-wanted THEN opposite:=true; END IF;
     IF sign(effect)=wanted AND NOT (family->>'family'=ANY(supporters)) AND EXISTS(SELECT 1 FROM jsonb_array_elements(claim->'evidence') ce WHERE ce->'questionRef'=family->'questionRef') THEN supporters:=array_append(supporters,family->>'family'); END IF;
    END LOOP;
    allowed:=cardinality(supporters)>=2 AND NOT opposite AND jsonb_array_length(claim->'counterevidence')=0;
   ELSIF claim->>'kind'='literary' THEN
    allowed:=(claim#>>'{literaryBridge,review}'='approved' AND claim#>>'{literaryBridge,grade}'='medium' AND claim#>'{literaryBridge,roleRef}'=score#>'{decision,selectedResultRef}') IS TRUE;
   END IF;
   SELECT coalesce(jsonb_agg(qf.composed_quote_v1(source,x) ORDER BY n),'[]') INTO evidence FROM jsonb_array_elements(claim->'evidence') WITH ORDINALITY a(x,n);
   SELECT coalesce(jsonb_agg(qf.composed_quote_v1(source,x) ORDER BY n),'[]') INTO counterevidence FROM jsonb_array_elements(claim->'counterevidence') WITH ORDINALITY a(x,n);
   paragraphs:=paragraphs||jsonb_build_array(jsonb_build_object('claimRef',claim->'ref','kind',claim->'kind','status',CASE WHEN allowed THEN 'accepted' ELSE 'facts-only' END,'text',CASE WHEN allowed THEN claim->>'text' ELSE '以下仅记录本轮具体情境中的选择，不作更广泛的概括。' END,'evidence',evidence,'counterevidence',counterevidence));
   IF jsonb_array_length(paragraphs)>=(volume->>'maxClaims')::integer THEN EXIT; END IF;
  END LOOP;
  IF jsonb_array_length(paragraphs)=0 THEN paragraphs:=jsonb_build_array(jsonb_build_object('claimRef',NULL,'kind','fallback','status','fallback','text',volume->'fallbackText','evidence','[]'::jsonb,'counterevidence','[]'::jsonb)); END IF;
  volumes:=volumes||jsonb_build_array(jsonb_build_object('id',volume->'id','title',volume->'title','paragraphs',paragraphs));
 END LOOP;
 SELECT jsonb_agg(jsonb_build_object('questionRef',q->'ref','optionRef',o->'ref','prompt',q->'prompt','optionText',o->'label','act',q->'act') ORDER BY n) INTO answers FROM jsonb_array_elements(score->'normalizedAnswers') WITH ORDINALITY a(answer,n) JOIN LATERAL jsonb_array_elements(core->'questions') q ON q#>>'{ref,id}'=answer->>'questionId' JOIN LATERAL jsonb_array_elements(q->'options') o ON o#>>'{ref,id}'=answer->>'optionId';
 SELECT jsonb_agg(jsonb_build_object('dimensionRef',d->'dimensionRef','label',c->'label','score',d->'score') ORDER BY n) INTO dimensions FROM jsonb_array_elements(score->'dimensions') WITH ORDINALITY a(d,n) JOIN LATERAL jsonb_array_elements(core->'dimensions') c ON c->'ref'=d->'dimensionRef';
 RETURN jsonb_build_object('schemaVersion','quiz-composed-report.v1','title',core->'title','notice','本报告是基于本轮情境选择的娱乐性文学匹配，不是人格诊断、能力评级或历史人物心理测量。','provenance',jsonb_build_object('canonicalContentSha256',scored->'canonicalContentSha256','templateRef',template->'ref','reportVersion',bindings->'reportVersion','evidenceFamilyVersion',core#>'{evidenceFamilies,version}','logicHash',score->'logicHash','inputHash',score->'inputHash','answersHash',score->'answersHash','matchingContextSha256',score->'matchingContextSha256'),'matching',jsonb_build_object('selected',qf.composed_role_v1(source,score#>'{decision,rankings,0}'),'runnerUp',CASE WHEN jsonb_array_length(score#>'{decision,rankings}')>1 THEN qf.composed_role_v1(source,score#>'{decision,rankings,1}') ELSE NULL END,'status',score#>'{decision,status}','gapTotal',score#>'{decision,gapTotal}'),'dimensions',dimensions,'answers',answers,'volumes',volumes);
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END $$;

CREATE FUNCTION qf.composed_assets_v1(source jsonb,chosen_character jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE neutral jsonb; refs jsonb; assets jsonb;
BEGIN
 neutral:=source#>'{bindings,slots,neutral}';
 refs:=jsonb_build_array(neutral->'cover',neutral->'reportPaper',neutral->'reportBorder',neutral->'seal',chosen_character->'reveal',chosen_character->'nameArt',chosen_character->'report',chosen_character->'poster');
 SELECT refs||coalesce(jsonb_agg(ref),'[]') INTO refs FROM jsonb_array_elements(neutral->'acts') a CROSS JOIN LATERAL (VALUES(a->'background'),(a->'questionPaper'),(a->'optionIdle'),(a->'optionSelected')) r(ref);
 SELECT jsonb_agg(jsonb_build_object('resourceRef',jsonb_build_object('productId',r->'productId','id',r->'id','version',r->'version'),'mediaType',r->'mediaType','bytes',r->'bytes','sha256',r->'sha256','width',r->'width','height',r->'height','purpose',r->'purpose','approval',r->'approval','alt',d->'alt') ORDER BY n) INTO assets FROM jsonb_array_elements(source#>'{bindings,resources}') WITH ORDINALITY resource(r,n) JOIN LATERAL jsonb_array_elements(source#>'{bindings,visualPresentation,resourceDescriptions}') d ON d->'resourceRef'=jsonb_build_object('productId',r->'productId','id',r->'id','version',r->'version') WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(refs) ref WHERE ref=jsonb_build_object('productId',r->'productId','id',r->'id','version',r->'version'));
 RETURN assets;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END $$;


CREATE FUNCTION qf.consumer_report_valid_v1(r qf.quiz_report) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE b jsonb; s jsonb; v jsonb; ref jsonb;
BEGIN
 IF qf.consumer_body_valid(r.binding_text,'complete',4096) IS NOT TRUE OR qf.consumer_body_valid(r.snapshot_text,'report',524288) IS NOT TRUE THEN RETURN false; END IF;
 b:=r.binding_text::jsonb;s:=r.snapshot_text::jsonb;v:=s->'view';
 ref:=jsonb_build_object('productId',r.product_id,'playVersionId',r.play_version_id,'playSnapshotSha256',r.play_snapshot_sha256::text,'keyId',r.key_id,'sessionId',r.session_id);
 RETURN (r.binding_sha256::text=qf.sha256_utf8(r.binding_text) AND r.snapshot_sha256::text=qf.sha256_utf8(r.snapshot_text) AND r.display_sha256::text=qf.sha256_utf8(qf.consumer_canonical(v))
 AND qf.consumer_moment(r.completed_at) IS NOT NULL
 AND b=jsonb_build_object('schemaVersion','quizforge.consumer-complete.v1','session',ref,'expectedStateRevision',r.state_revision,'consumerStateAnswersSha256',r.consumer_state_answers_sha256::text,'progressSha256',r.progress_sha256::text,'completionKey',r.completion_key)
 AND s->'binding'=b AND v->'session'=ref AND v->>'reportId'=r.id::text AND v->>'completedAt'=qf.consumer_moment(r.completed_at) AND v->>'completionBindingSha256'=r.binding_sha256::text
 AND qf.sha256_utf8(qf.consumer_canonical(jsonb_build_object('schemaVersion','quizforge.consumer-state-answers.v1','answers',s->'answers')))=r.consumer_state_answers_sha256::text
 AND qf.sha256_utf8(qf.consumer_canonical(jsonb_build_object('schemaVersion','quizforge.consumer-state-progress.v1','progress',s->'progress')))=r.progress_sha256::text
 AND s->'score'->'score'->>'answersHash'=v->'display'->>'answersHash' AND s->'score'->'score'->>'logicHash'=v->'display'->>'logicHash'
 AND s->'score'->'score'->'decision'->'selectedResultRef'=v->'display'->'selectedResultRef' AND s->'score'->'reportTemplateRef'=v->'display'->'reportTemplateRef') IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.consumer_report_valid(r qf.quiz_report) RETURNS boolean LANGUAGE plpgsql STABLE STRICT SET search_path=pg_catalog AS $$
DECLARE is_v2 boolean; b jsonb; s jsonb; v jsonb; d jsonb; score jsonb; ref jsonb; play jsonb; parent jsonb; context_sha text;
BEGIN
 is_v2:=qf.consumer_protocol_v2(r.product_id,r.play_version_id,r.play_snapshot_sha256::text);
 IF is_v2 IS NULL THEN RETURN false; END IF;
 IF NOT is_v2 THEN RETURN (r.matching_context_sha256 IS NULL AND qf.consumer_report_valid_v1(r)) IS TRUE; END IF;
 IF (r.matching_context_sha256 IS NOT NULL AND r.matching_context_sha256 ~ '^[a-f0-9]{64}$' AND qf.consumer_body_valid_v2(r.binding_text,'complete',4096) AND qf.consumer_body_valid_v2(r.snapshot_text,'report',524288)) IS NOT TRUE THEN RETURN false; END IF;
 b:=r.binding_text::jsonb;s:=r.snapshot_text::jsonb;v:=s->'view';d:=v->'display';score:=s#>'{score,score}';play:=s#>'{play,snapshot}';parent:=play->'parentSnapshot';
 ref:=jsonb_build_object('productId',r.product_id,'playVersionId',r.play_version_id,'playSnapshotSha256',r.play_snapshot_sha256::text,'keyId',r.key_id,'sessionId',r.session_id);
 context_sha:=qf.sha256_utf8(E'quizforge:quiz-matching-context.v1\n'||qf.consumer_canonical(s->'matchingContext'));
 RETURN (r.binding_sha256::text=qf.sha256_utf8(r.binding_text) AND r.snapshot_sha256::text=qf.sha256_utf8(r.snapshot_text) AND r.display_sha256::text=qf.sha256_utf8(qf.consumer_canonical(v)) AND qf.consumer_moment(r.completed_at) IS NOT NULL
 AND b=jsonb_build_object('schemaVersion','quizforge.consumer-complete.v2','session',ref,'expectedStateRevision',r.state_revision,'consumerStateAnswersSha256',r.consumer_state_answers_sha256::text,'progressSha256',r.progress_sha256::text,'matchingContextSha256',r.matching_context_sha256::text,'completionKey',r.completion_key)
 AND s->'binding'=b AND v->'session'=ref AND v->>'reportId'=r.id::text AND v->>'completedAt'=qf.consumer_moment(r.completed_at) AND v->>'completionBindingSha256'=r.binding_sha256::text
 AND play->>'schemaVersion'='quizforge.internal-play-snapshot.v2' AND parent->>'schemaVersion'='quizforge.internal-version-snapshot.v2'
 AND v->'parent'=play->'parent' AND v->'renderer'=play->'renderer' AND v->'font'=parent->'font' AND v->'mapping'=play->'mapping' AND v->'mappingSha256'=play->'mappingSha256'
 AND jsonb_build_object('presentationMode',d->'presentationMode','exports',d->'exports')=play->'presentation'
 AND qf.sha256_utf8(qf.consumer_canonical(jsonb_build_object('schemaVersion','quizforge.consumer-state-answers.v1','answers',s->'answers')))=r.consumer_state_answers_sha256::text
 AND qf.sha256_utf8(qf.consumer_canonical(jsonb_build_object('schemaVersion','quizforge.consumer-state-progress.v1','progress',s->'progress')))=r.progress_sha256::text
 AND s->'matchingContext'<>'null'::jsonb AND s->'matchingContext'=score->'matchingContext' AND context_sha=r.matching_context_sha256::text AND context_sha=score->>'matchingContextSha256' AND context_sha=d->>'matchingContextSha256'
 AND qf.sha256_utf8(E'quizforge:quiz-answers.v2\n'||qf.consumer_canonical(score->'normalizedAnswers'))=score->>'answersHash'
 AND qf.sha256_utf8(E'quizforge:quiz-input.v2\n'||qf.consumer_canonical(jsonb_build_object('schemaVersion','quiz-scoring-input.v2','answers',score->'normalizedAnswers','matchingContext',s->'matchingContext')))=score->>'inputHash'
 AND score->'engine'=parent#>'{versions,engine}' AND score->>'logicHash'=parent->>'logicHash' AND score->>'productId'=r.product_id AND score->'contentVersion'=parent#>'{versions,contentVersion}'
 AND s#>'{score,canonicalContentSha256}'=parent#>'{target,canonicalContentSha256}' AND s#>'{score,reportVersion}'=parent#>'{versions,reportVersion}'
 AND d->'canonicalContentSha256'=s#>'{score,canonicalContentSha256}' AND d->'contentVersion'=score->'contentVersion' AND d->'reportVersion'=s#>'{score,reportVersion}' AND d->'logicHash'=score->'logicHash' AND d->'answersHash'=score->'answersHash' AND d->'inputHash'=score->'inputHash'
 AND score#>'{decision,selectedResultRef}'=d->'selectedResultRef' AND s#>'{score,reportTemplateRef}'=d->'reportTemplateRef'
 AND d->>'bodySha256'=qf.sha256_utf8(qf.consumer_canonical(d->'body'))) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.protect_consumer_report() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE p qf.internal_play_version; s qf.consumer_session; body jsonb; expected jsonb; is_v2 boolean; source jsonb; score jsonb; display jsonb; normalized jsonb; chosen_character jsonb; expected_body jsonb; k qf.access_key;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'IMMUTABLE_CONSUMER_REPORT' USING ERRCODE='23514'; END IF;
 IF NOT pg_try_advisory_xact_lock_shared(72461,2) THEN RAISE EXCEPTION 'CONSUMER_MAINTENANCE_BUSY' USING ERRCODE='55P03'; END IF;
 PERFORM 1 FROM qf.access_key WHERE id=NEW.key_id FOR UPDATE;
 SELECT * INTO s FROM qf.consumer_session WHERE id=NEW.session_id AND key_id=NEW.key_id FOR UPDATE;
 SELECT * INTO p FROM qf.internal_play_version WHERE id=NEW.play_version_id AND product_id=NEW.product_id AND snapshot_sha256=NEW.play_snapshot_sha256;
 IF s.id IS NULL OR p.id IS NULL THEN RAISE EXCEPTION 'CONSUMER_REPORT_SOURCE_MISSING' USING ERRCODE='23514'; END IF;
 expected:=jsonb_build_object('schemaVersion','quizforge.internal-play-receipt.v1','id',p.id,'slot',p.slot,'binding',p.binding_text::jsonb,'bindingSha256',p.binding_sha256::text,'snapshotSha256',p.snapshot_sha256::text,'createdBy',p.created_by,'createdAt',qf.consumer_moment(p.created_at),'purpose','internal-test','publicationApproved',false);
 body:=NEW.snapshot_text::jsonb;
 IF body->'play' IS DISTINCT FROM jsonb_build_object('play',expected,'snapshot',p.snapshot_text::jsonb) OR body->'answers' IS DISTINCT FROM s.answers_text::jsonb->'answers' OR body->'progress' IS DISTINCT FROM s.progress_text::jsonb->'progress' THEN RAISE EXCEPTION 'CONSUMER_REPORT_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 is_v2:=qf.consumer_protocol_v2(NEW.product_id,NEW.play_version_id,NEW.play_snapshot_sha256::text);
 IF is_v2 IS NULL THEN RAISE EXCEPTION 'CONSUMER_PROTOCOL_MISMATCH' USING ERRCODE='23514'; END IF;
 IF NOT is_v2 THEN
  IF NEW.matching_context_sha256 IS NOT NULL OR s.matching_context_text IS NOT NULL OR s.matching_context_sha256 IS NOT NULL THEN RAISE EXCEPTION 'CONSUMER_PROTOCOL_MISMATCH' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF (NEW.matching_context_sha256 IS NOT NULL AND s.matching_context_text IS NOT NULL AND s.matching_context_sha256 IS NOT NULL AND NEW.matching_context_sha256=s.matching_context_sha256 AND s.matching_context_text<>'null' AND qf.consumer_canonical(body->'matchingContext')=s.matching_context_text) IS NOT TRUE THEN RAISE EXCEPTION 'CONSUMER_REPORT_CONTEXT_MISMATCH' USING ERRCODE='23514'; END IF;
 SELECT * INTO k FROM qf.access_key WHERE id=NEW.key_id;
 IF k.revoked_at IS NOT NULL OR k.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'CONSUMER_REPORT_DEADLINE' USING ERRCODE='23514'; END IF;
 SELECT d.canonical_content_text::jsonb INTO source FROM qf.product_version v JOIN qf.draft_revision d ON(d.product_id,d.draft_id,d.revision)=(v.product_id,v.draft_id,v.revision) WHERE (v.id,v.product_id,v.snapshot_sha256)=(p.parent_version_id,p.product_id,p.parent_snapshot_sha256);
 IF (source->>'schemaVersion'='quizpack-content.v3' AND qf.sha256_utf8(qf.consumer_canonical(source))=p.snapshot_text::jsonb#>>'{parentSnapshot,target,canonicalContentSha256}') IS NOT TRUE THEN RAISE EXCEPTION 'CONSUMER_REPORT_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 score:=body#>'{score,score}';display:=body#>'{view,display}';
 SELECT jsonb_agg(a ORDER BY n) INTO normalized FROM jsonb_array_elements(source#>'{core,questions}') WITH ORDINALITY question(q,n) JOIN LATERAL jsonb_array_elements(s.answers_text::jsonb->'answers') a ON a->>'questionId'=q#>>'{ref,id}';
 IF (jsonb_array_length(normalized)=jsonb_array_length(source#>'{core,questions}') AND normalized=score->'normalizedAnswers'
  AND score->>'logicHash'=qf.sha256_utf8(E'quizforge:quiz-logic.v2\n'||qf.consumer_canonical(source#>'{core,scoringDefinition}'))
  AND body#>'{matchingContext,policyRef}'=source#>'{core,scoringDefinition,matchingPolicy,ref}'
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(source#>'{core,scoringDefinition,profiles}') profile WHERE profile->'resultRef'=score#>'{decision,selectedResultRef}' AND (body#>>'{matchingContext,preference}'='any' OR body#>>'{matchingContext,preference}'=profile->>'sex') AND profile->'kind' IN (SELECT value FROM jsonb_array_elements(source#>'{core,scoringDefinition,matchingPolicy,allowedKinds}')))) IS NOT TRUE THEN RAISE EXCEPTION 'CONSUMER_REPORT_INPUT_MISMATCH' USING ERRCODE='23514'; END IF;
 expected_body:=qf.composed_body_v1(source,body->'score');
 IF expected_body IS NULL OR display->'body' IS DISTINCT FROM expected_body THEN RAISE EXCEPTION 'CONSUMER_REPORT_BODY_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 SELECT c INTO chosen_character FROM jsonb_array_elements(source#>'{bindings,slots,characters}') c WHERE c->'resultRef'=score#>'{decision,selectedResultRef}';
 IF chosen_character IS NULL OR display->'slots' IS DISTINCT FROM jsonb_build_object('neutral',source#>'{bindings,slots,neutral}','character',chosen_character) OR display->'assets' IS DISTINCT FROM qf.composed_assets_v1(source,chosen_character) THEN RAISE EXCEPTION 'CONSUMER_REPORT_RESOURCE_SCOPE' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION qf.protect_product_asset() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE v qf.quizpack_validation; item jsonb; declaration jsonb;
BEGIN
 SELECT * INTO v FROM qf.quizpack_validation WHERE product_id=NEW.product_id AND id=NEW.source_validation_id;
 IF v.validated_at IS NULL THEN RAISE EXCEPTION 'ASSET_SOURCE' USING ERRCODE='23514'; END IF;
 SELECT value INTO item FROM jsonb_array_elements(v.asset_set_text::jsonb->'resources') WHERE value->>'productId'=NEW.product_id AND value->>'resourceId'=NEW.resource_id AND value->>'resourceVersion'=NEW.resource_version;
 SELECT value INTO declaration FROM jsonb_array_elements((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN v.canonical_content_text::jsonb#>'{bindings,resources}' ELSE v.canonical_content_text::jsonb->'resources' END)) WHERE value->>'productId'=NEW.product_id AND value->>'id'=NEW.resource_id AND value->>'version'=NEW.resource_version;
 IF (item->>'blobSha256'=NEW.blob_sha256 AND item->>'declarationSha256'=NEW.declaration_sha256 AND declaration=NEW.declaration_text::jsonb) IS NOT TRUE THEN RAISE EXCEPTION 'ASSET_SET' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION qf.validation_ready_assets() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE v qf.quizpack_validation; item jsonb; p qf.product_asset; declaration jsonb; count integer:=0;
BEGIN
 SELECT * INTO v FROM qf.quizpack_validation WHERE id=NEW.id;
 IF v.status<>'ready' THEN RETURN NULL; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(v.asset_set_text::jsonb->'resources') LOOP
  SELECT * INTO p FROM qf.product_asset WHERE product_id=v.product_id AND resource_id=item->>'resourceId' AND resource_version=item->>'resourceVersion';
  SELECT value INTO declaration FROM jsonb_array_elements((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN v.canonical_content_text::jsonb#>'{bindings,resources}' ELSE v.canonical_content_text::jsonb->'resources' END)) WHERE value->>'productId'=v.product_id AND value->>'id'=item->>'resourceId' AND value->>'version'=item->>'resourceVersion';
  IF (p.blob_sha256=item->>'blobSha256' AND p.declaration_sha256=item->>'declarationSha256' AND p.declaration_text::jsonb=declaration AND qf.product_asset_declaration_valid(p.product_id,p.resource_id,p.resource_version,p.blob_sha256,p.purpose,p.declaration_text)) IS NOT TRUE THEN RAISE EXCEPTION 'VALIDATION_ASSET_INCOMPLETE' USING ERRCODE='23514'; END IF;
  count:=count+1;
 END LOOP;
 IF count<>v.resource_count THEN RAISE EXCEPTION 'VALIDATION_ASSET_INCOMPLETE' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;

ALTER TABLE qf.draft_revision DROP CONSTRAINT draft_revision_engine_id_check;
ALTER TABLE qf.draft_revision ADD CONSTRAINT draft_revision_engine_id_check CHECK(
 ((content_schema_version IN ('quizpack-content.v1','quizpack-content.v2') AND engine_id IN ('dimensions','archetype'))
 OR (content_schema_version='quizpack-content.v3' AND engine_id='archetype-l1')) IS TRUE
);


-- Replacing CHECK helpers does not revalidate existing rows. Preserve every old byte and fail closed.
DO $$ DECLARE v qf.quizpack_validation; p qf.product_version; play qf.internal_play_version; s qf.consumer_session; r qf.quiz_report; BEGIN
 FOR v IN SELECT * FROM qf.quizpack_validation LOOP IF qf.validation_shape_valid(v) IS NOT TRUE OR qf.validation_file_stop_controls_valid(v.archive_policy_version,v.id,v.attempts_text,v.evidence_metadata_text) IS NOT TRUE THEN RAISE EXCEPTION 'D2_EXISTING_VALIDATION' USING ERRCODE='23514'; END IF; END LOOP;
 FOR p IN SELECT * FROM qf.product_version LOOP IF qf.internal_version_valid(p) IS NOT TRUE THEN RAISE EXCEPTION 'D2_EXISTING_VERSION' USING ERRCODE='23514'; END IF; END LOOP;
 FOR play IN SELECT * FROM qf.internal_play_version LOOP IF qf.consumer_play_valid(play) IS NOT TRUE THEN RAISE EXCEPTION 'D2_EXISTING_PLAY' USING ERRCODE='23514'; END IF; END LOOP;
 FOR s IN SELECT * FROM qf.consumer_session LOOP IF qf.consumer_session_valid(s) IS NOT TRUE THEN RAISE EXCEPTION 'D2_EXISTING_SESSION' USING ERRCODE='23514'; END IF; END LOOP;
 FOR r IN SELECT * FROM qf.quiz_report LOOP IF qf.consumer_report_valid(r) IS NOT TRUE THEN RAISE EXCEPTION 'D2_EXISTING_REPORT' USING ERRCODE='23514'; END IF; END LOOP;
END $$;

REVOKE ALL ON FUNCTION qf.consumer_schema_v2(text),qf.consumer_json_valid_v2(jsonb,jsonb,integer),qf.consumer_body_valid_v2(text,text,integer),qf.consumer_protocol_v2(text,uuid,text),qf.consumer_session_valid_v1(qf.consumer_session),qf.consumer_report_valid_v1(qf.quiz_report),qf.composed_quote_v1(jsonb,jsonb),qf.composed_role_v1(jsonb,jsonb),qf.composed_body_v1(jsonb,jsonb),qf.composed_assets_v1(jsonb,jsonb) FROM PUBLIC;
